"""Seam coverage for the 「正在載入輸入法碼表」 toast (upstream #639).

The toast must be driven by the real pending state of the loader — the single
``future`` slot on ``cinbase.cintablebase.CinTableBase`` — so:

* a key that lands while a background table load is still in flight shows it;
* once the future is done the key sequence no longer re-arms it, even when the
  service is left without a table object (a completed/failed load).

Each case drives the real 速成 (chesimplex) service with synthesized key
events and asserts on the reply the C++ client would see.
"""

import concurrent.futures
import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402

LOADING_MESSAGE = '正在載入輸入法碼表，請稍候...'


class CinbaseLoadingMessageTests(CinbaseKeyHarness):
    # The CinTable singleton is shared by every service in the process, so the
    # done future holding the 速成 table is carried between these tests.
    _savedTableFuture = None

    def setUp(self):
        super().setUp()
        from input_methods.chesimplex import chesimplex_ime
        self.module = chesimplex_ime

    def tearDown(self):
        table = self.module.CinTable
        if table.cin is not None:
            done = concurrent.futures.Future()
            done.set_result(table.cin)
            table.future = done
            CinbaseLoadingMessageTests._savedTableFuture = done
        elif CinbaseLoadingMessageTests._savedTableFuture is not None:
            table.future = CinbaseLoadingMessageTests._savedTableFuture
        super().tearDown()

    def test_pending_load_shows_the_message(self):
        service = self.activate_chesimplex()
        pending = concurrent.futures.Future()  # never completed: a slow load
        self.module.CinTable.future = pending

        self.send(service, ord('a'), ord('a'), printable=True)

        self.assertIn("showMessage", service.currentReply)
        self.assertEqual(service.currentReply["showMessage"]["message"],
                         LOADING_MESSAGE)
        pending.set_result(service.cin)

    def test_completed_load_stops_emitting_the_message(self):
        service = self.activate_chesimplex()
        table = self.module.CinTable
        loaded = table.cin
        pending = concurrent.futures.Future()
        table.future = pending
        self.send(service, ord('a'), ord('a'), printable=True)
        self.assertEqual(service.currentReply["showMessage"]["message"],
                         LOADING_MESSAGE)
        pending.set_result(loaded)

        # The report's repro: a quick key sequence right after the load.
        # Every key is answered, and none of them re-arms the toast.
        toasts = []
        for code in (0x38, 0x20, ord('a'), ord('b')):  # '*' space a b
            self.send(service, code, code, printable=True)
            reply = service.currentReply
            self.assertIsInstance(reply, dict,
                                  "key %r got no reply at all" % code)
            if "showMessage" in reply:
                toasts.append(reply["showMessage"]["message"])
        self.assertEqual([], toasts,
                         "the toast was re-armed after the load")

    def test_done_future_without_a_table_emits_no_stale_message(self):
        service = self.activate_chesimplex()
        done = concurrent.futures.Future()
        done.set_result(None)  # the loader finished; nothing pending
        self.module.CinTable.future = done
        service.cin = None

        self.send(service, 0x20, 0x20)

        self.assertNotIn("showMessage", service.currentReply)


if __name__ == "__main__":
    unittest.main()
